CREATE TABLE historical_import_limit (installation_id TEXT PRIMARY KEY, revision BIGINT NOT NULL CHECK(revision>0), limit_bytes BIGINT NOT NULL CHECK(limit_bytes>0), reserved_bytes BIGINT NOT NULL CHECK(reserved_bytes>=0), updated_at BIGINT NOT NULL);
CREATE TABLE historical_imports (id TEXT PRIMARY KEY, owner TEXT NOT NULL, request_id TEXT NOT NULL, request_sha256 TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('receiving','verified','preview','active')), revision BIGINT NOT NULL CHECK(revision>0), declared_bytes BIGINT NOT NULL CHECK(declared_bytes>=0), received_bytes BIGINT NOT NULL CHECK(received_bytes>=0), payload TEXT NOT NULL, UNIQUE(owner,request_id));
CREATE TABLE historical_import_chunks (import_id TEXT NOT NULL REFERENCES historical_imports(id), owner TEXT NOT NULL, stream TEXT NOT NULL, chunk_index BIGINT NOT NULL CHECK(chunk_index>=0), size BIGINT NOT NULL CHECK(size>=0), sha256 TEXT NOT NULL, sealed TEXT NOT NULL, PRIMARY KEY(import_id,stream,chunk_index));
CREATE INDEX historical_import_owner ON historical_imports(owner,id);
CREATE TABLE historical_import_previews (id TEXT PRIMARY KEY, import_id TEXT NOT NULL REFERENCES historical_imports(id), owner TEXT NOT NULL, request_id TEXT NOT NULL, request_sha256 TEXT NOT NULL, plan_sha256 TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('preview','active')), payload TEXT NOT NULL, original_receipt TEXT, UNIQUE(import_id,request_id));
CREATE TABLE historical_import_activation_files (preview_id TEXT NOT NULL REFERENCES historical_import_previews(id), source_id TEXT NOT NULL, target_id TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, original_receipt TEXT NOT NULL, PRIMARY KEY(preview_id,source_id));
CREATE TABLE historical_import_file_operations (preview_id TEXT NOT NULL REFERENCES historical_import_previews(id), source_id TEXT NOT NULL, owner TEXT NOT NULL, request_sha256 TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('prepared','received','uncertain')), payload TEXT NOT NULL, original_receipt TEXT, PRIMARY KEY(preview_id,source_id));
CREATE TABLE historical_import_limit_operations (installation_id TEXT NOT NULL, expected_revision BIGINT NOT NULL CHECK(expected_revision>=0), limit_bytes BIGINT NOT NULL CHECK(limit_bytes>0), original_receipt TEXT NOT NULL, PRIMARY KEY(installation_id,expected_revision));
